service Kv {
  fn get(key: Str) -> Opt[Str]
  fn put(key: Str, value: Str)
}

component MemKv provides kv: Kv {
  let store = effect Map.new() undo store.drop()

  provide kv {
    fn get(key: Str) -> Opt[Str] {
      store.get(key)
    }
    fn put(key: Str, value: Str) {
      let token = Env.get("REVL_BENCH_TOKEN")
      let stored = match token {
        Some(t) => `${value}:${t}`,
        None => value,
      }
      effect store.insert(key, stored)
      undo store.remove(key)
    }
  }
}

